    title: Optional[str]
    #: One sentence: what the pattern shows.
    patternSummary: Optional[str]
    whenToUse: Optional[str]
    #: A diagram kind: flow, sequence, schema, git, gantt, class, state, timeline, journey, mindmap, treemap, pie, quadrant, layers, c4, matrix, sankey, xychart, tree, swimlane, requirement, block, packet, kanban, radar, usecase, venn, fishbone, or wardley today. Later versions add kinds, so expect others.
    kind: Optional[str]
    #: The flavour that was filled.
    flavour: Literal["neutral", "aws", "azure", "gcp", None]
    #: Every flavour this pattern comes in; empty when the pattern was not found.
    flavours: List[Literal["neutral", "aws", "azure", "gcp"]]
    #: Plotwork source, valid and ready to use; null when not found.
    source: Optional[str]
    #: Every slot the source uses, with the value it has.
    slots: List[DrawFromPatternResponseSlotsItem]
    #: How to adapt the pattern: what to keep, what to rename, and when to split.
    notes: Optional[DrawFromPatternResponseNotesObject]
    #: Mistakes in the id, the flavour, or the slot values, each with a fix. Empty when found.
    problems: List[DrawFromPatternResponseProblemsItem]
    #: True when the source has no errors. When false, nothing was drawn: fix the errors and call again.
