    report: List[SyncMarkdownResponseReportItem]
    summary: SyncMarkdownResponseSummary
    caps: SyncMarkdownResponseCaps
    #: Present when page or pageSize was sent: which pictures files holds, and the next page.
    pages: NotRequired[SyncMarkdownResponsePages]
    #: The next step in one sentence.
    next: str


