    #: In plain words: what this answer holds and how to get the rest.
    howToGetAKind: str
    #: Header keywords: the first line names the kind.
    kinds: List[str]
    #: The overview lists every kind in the order of kinds, with its header, noun, and summary, and a pointer in more. A kind answer holds that kind alone, in full.
    kindDetails: List[SyntaxResponseKindDetailsItem]
    nodeTypes: NotRequired[List[SyntaxResponseNodeTypesItem]]
    tones: NotRequired[List[Literal["neutral", "blue", "violet", "aqua", "orange", "green", "amber", "red"]]]
    #: Values for direction= on a flow header.
    directions: NotRequired[List[Literal["auto", "right", "down", "left", "up"]]]
    arrows: NotRequired[List[SyntaxResponseArrowsItem]]
    #: Frames a sequence diagram can wrap around messages.
    blockTypes: NotRequired[List[Literal["alt", "opt", "loop", "par"]]]
    #: Flags a schema column row may carry.
    columnFlags: NotRequired[List[Literal["pk", "fk", "unique", "nullable"]]]
    #: The color schemes a picture is drawn in, chosen where it is drawn (a tool's scheme argument), not in the source.
    schemes: NotRequired[List[Literal["light", "dark"]]]
    #: Colour themes: theme=<name> on the header of any kind, such as flow "Title" theme=ocean. plotwork is the default; contrast reaches WCAG AAA. Each holds light and dark, and tones keep their meaning. An organisation's brand, on the hosted service, wins over it.
    themes: NotRequired[List[Literal["plotwork", "slate", "ocean", "forest", "sunset", "mono", "contrast"]]]
    iconSets: NotRequired[List[Literal["lucide", "simple", "status", "aws", "gcp", "azure", "alibaba", "oci", "ibm", "cloudflare", "digitalocean", "vercel", "k8s"]]]
    #: Number of bundled icons; use search_icons to find names.
    iconCount: NotRequired[int]
    #: Cloud and platform providers, each an icon set holding the provider (set:cloud) and its products.
    iconProviders: NotRequired[List[SyntaxResponseIconProvidersItem]]
    #: A dashed frame around members that may sit in different groups; it owns none of them.
    overlay: NotRequired[SyntaxResponseOverlay]
    #: How a flow group looks and what it accepts; its corner tab shows its icon and name.
    group: NotRequired[SyntaxResponseGroup]
    #: Options that shape a flow diagram: spacing=, edges= and fit= on the header, main=on on an edge, and the align statement.
    flowLook: NotRequired[List[SyntaxResponseFlowLookItem]]
    #: Options that animate a line (animate=on makes dashes travel toward the arrowhead) or number the steps of a flow or sequence (numbered=on, start=, and step= on a line). All are off by default.
    lineOptions: NotRequired[List[SyntaxResponseLineOptionsItem]]
    #: Edge labels that name an outcome and get its status icon automatically (a tick for yes, a cross for no, a clock for expired); one per icon in a kind answer, every one in topic icon-words. icon=none on the edge removes it.
    labelIcons: NotRequired[List[SyntaxResponseLabelIconsItem]]
    #: The icons a flow edge label draws when it names a relationship with a verb. icon= on the edge wins, icon=none removes it, and icons=off on the header turns them all off.
    verbIcons: NotRequired[List[SyntaxResponseVerbIconsItem]]
    #: How to make a flow diagram look finished: verbs on arrows, role= on lines that mean something, typed groups, product names.
    style: NotRequired[List[str]]
    #: Items with no icon= get the icon their label names for certain (a brand, a cloud product, a common role). icon=none keeps one item plain; icons=off on the header keeps them all plain.
    autoIcons: NotRequired[SyntaxResponseAutoIcons]
    #: The plain icons for common roles, drawn on flow and sequence service and external items, C4 elements, layers blocks, mind map topics, and swimlane lanes. The last role word of the label wins.
    roleIcons: NotRequired[List[SyntaxResponseRoleIconsItem]]
    #: Colored status and outcome icons: a green check, a red X, and so on.
    statusIcons: NotRequired[List[SyntaxResponseStatusIconsItem]]
    #: Bounds and quality thresholds.
    limits: NotRequired[SyntaxResponseLimits]
    #: How to edit an existing Plotwork SVG: read it back with read_diagram, change the source, draw it, and save or publish it again.
    editing: NotRequired[SyntaxResponseEditing]
    diagnosticCodes: NotRequired[List[SyntaxResponseDiagnosticCodesItem]]
    #: Tested examples: the overview holds the ones for the kinds the shared tables describe in full, a kind answer holds its own.
    examples: List[SyntaxResponseExamplesItem]
    #: Only for topic import-formats: every format import_source reads, a line each.
    importFormats: NotRequired[List[SyntaxResponseImportFormatsItem]]


