PublishAnswer = Union[PublishedDiagram, RoutedPublish]


class DiagramsOperations:
    """The ``diagrams`` operations."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def compare(self, **body: Unpack[CompareDiagramsInput]) -> CompareDiagramsResponse:
        """Say what changed between two versions of a diagram. ``POST /v1/diagrams/compare``"""
        return cast("CompareDiagramsResponse", self._transport.request("POST", "/v1/diagrams/compare", idempotent=True, body=body))

    def convert_mermaid(self, **body: Unpack[ConvertMermaidInput]) -> ConvertMermaidResponse:
        """Convert one Mermaid diagram. ``POST /v1/diagrams/convert-mermaid``"""
        return cast("ConvertMermaidResponse", self._transport.request("POST", "/v1/diagrams/convert-mermaid", idempotent=True, body=body))

    def draw(self, **body: Unpack[DrawDiagramInput]) -> DrawDiagramResponse:
        """Check, describe, and draw a diagram. ``POST /v1/diagrams/draw``"""
        return cast("DrawDiagramResponse", self._transport.request("POST", "/v1/diagrams/draw", idempotent=True, body=body))

    def edit(self, **body: Unpack[EditDiagramInput]) -> EditDiagramResponse:
        """Change diagram source with small typed operations. ``POST /v1/diagrams/edit``"""
        return cast("EditDiagramResponse", self._transport.request("POST", "/v1/diagrams/edit", idempotent=True, body=body))

    def embed(self, **body: Unpack[EmbedDiagramInput]) -> EmbedDiagramResponse:
        """Write a snippet that shows a picture with the viewer. ``POST /v1/diagrams/embed``"""
        return cast("EmbedDiagramResponse", self._transport.request("POST", "/v1/diagrams/embed", idempotent=True, body=body))

    def outline(self, **body: Unpack[DiagramSourceInput]) -> OutlineResponse:
        """Describe diagram source as text. ``POST /v1/diagrams/outline``"""
        return cast("OutlineResponse", self._transport.request("POST", "/v1/diagrams/outline", idempotent=True, body=body))

    def publish(self, **body: Unpack[PublishDiagramBody]) -> PublishAnswer:
        """Publish a diagram and get a link. ``POST /v1/diagrams/publish``"""
        return cast("PublishAnswer", self._transport.request("POST", "/v1/diagrams/publish", idempotent=False, body=body))

    def read(self, **body: Unpack[ReadDiagramInput]) -> ReadDiagramResponse:
        """Read the source back out of a Plotwork SVG. ``POST /v1/diagrams/read``"""
        return cast("ReadDiagramResponse", self._transport.request("POST", "/v1/diagrams/read", idempotent=True, body=body))

    def render(self, **body: Unpack[RenderInput]) -> RenderResponse:
        """Render diagram source to SVG. ``POST /v1/diagrams/render``"""
        return cast("RenderResponse", self._transport.request("POST", "/v1/diagrams/render", idempotent=True, body=body))

    def suggest(self, **body: Unpack[SuggestDiagramInput]) -> SuggestDiagramResponse:
        """Choose the kind of diagram for a request. ``POST /v1/diagrams/suggest``"""
        return cast("SuggestDiagramResponse", self._transport.request("POST", "/v1/diagrams/suggest", idempotent=True, body=body))

    def validate(self, **body: Unpack[DiagramSourceInput]) -> ValidateResponse:
        """Check diagram source. ``POST /v1/diagrams/validate``"""
        return cast("ValidateResponse", self._transport.request("POST", "/v1/diagrams/validate", idempotent=True, body=body))


class IconsOperations:
    """The ``icons`` operations."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def search(self, *, q: str, limit: Optional[int] = None) -> IconSearchResponse:
        """Find bundled icon names. ``GET /v1/icons``"""
        return cast("IconSearchResponse", self._transport.request("GET", "/v1/icons", idempotent=True, query={"q": q, "limit": limit}))

    def map(self, **body: Unpack[MapIconsInput]) -> MapIconsResponse:
        """Choose icons for many names at once. ``POST /v1/icons/map``"""
        return cast("MapIconsResponse", self._transport.request("POST", "/v1/icons/map", idempotent=True, body=body))


class LibraryOperations:
    """The ``library`` operations."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def list(self, *, limit: Optional[int] = None, cursor: Optional[str] = None, folder: Optional[str] = None) -> LibraryPage:
        """List the diagrams a key or an app's token can see. ``GET /v1/library``"""
        return cast("LibraryPage", self._transport.request("GET", "/v1/library", idempotent=True, query={"limit": limit, "cursor": cursor, "folder": folder}))


class MarkdownOperations:
    """The ``markdown`` operations."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def plan(self, **body: Unpack[PlanDocumentInput]) -> PlanDocumentResponse:
        """Find the sections of a document a picture would help. ``POST /v1/markdown/plan``"""
        return cast("PlanDocumentResponse", self._transport.request("POST", "/v1/markdown/plan", idempotent=True, body=body))

    def sync(self, **body: Unpack[SyncMarkdownInput]) -> SyncMarkdownResponse:
        """Turn a document's diagram fences into pictures. ``POST /v1/markdown/sync``"""
        return cast("SyncMarkdownResponse", self._transport.request("POST", "/v1/markdown/sync", idempotent=True, body=body))


class PatternsOperations:
    """The ``patterns`` operations."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def check(self, **body: Unpack[CheckPatternInput]) -> CheckPatternResponse:
        """Check a pattern file. ``POST /v1/patterns/check``"""
        return cast("CheckPatternResponse", self._transport.request("POST", "/v1/patterns/check", idempotent=True, body=body))

    def draw(self, **body: Unpack[DrawFromPatternInput]) -> DrawFromPatternResponse:
        """Fill a pattern and draw it. ``POST /v1/patterns/draw``"""
        return cast("DrawFromPatternResponse", self._transport.request("POST", "/v1/patterns/draw", idempotent=True, body=body))

    def find(self, **body: Unpack[FindPatternInput]) -> FindPatternResponse:
        """Find a ready-made architecture diagram. ``POST /v1/patterns/find``"""
        return cast("FindPatternResponse", self._transport.request("POST", "/v1/patterns/find", idempotent=True, body=body))

    def get(self, **body: Unpack[GetPatternInput]) -> GetPatternResponse:
        """Read a pattern filled for a flavour. ``POST /v1/patterns/get``"""
        return cast("GetPatternResponse", self._transport.request("POST", "/v1/patterns/get", idempotent=True, body=body))


class Operations:
    """Every ``/v1`` operation, as groups of methods that each send one request through the transport."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport
        self.diagrams = DiagramsOperations(transport)
        self.icons = IconsOperations(transport)
        self.library = LibraryOperations(transport)
        self.markdown = MarkdownOperations(transport)
        self.patterns = PatternsOperations(transport)

    def import_source(self, **body: Unpack[ImportSourceInput]) -> ImportSourceResponse:
        """Turn a file of another format into a diagram. ``POST /v1/import``"""
        return cast("ImportSourceResponse", self._transport.request("POST", "/v1/import", idempotent=True, body=body))

    def me(self) -> Me:
        """Read who a key or an app's token acts as. ``GET /v1/me``"""
        return cast("Me", self._transport.request("GET", "/v1/me", idempotent=True))

    def vocabulary(self, *, kind: Optional[Literal["flow", "sequence", "schema", "git", "gantt", "class", "state", "timeline", "journey", "mindmap", "treemap", "pie", "quadrant", "layers", "c4", "matrix", "sankey", "xychart", "tree", "swimlane", "requirement", "block", "packet", "kanban", "radar", "usecase", "venn", "fishbone", "wardley"]] = None, topic: Optional[Literal["import-formats", "icon-words"]] = None) -> SyntaxResponse:
        """Get the diagram language reference. ``GET /v1/vocabulary``"""
        return cast("SyntaxResponse", self._transport.request("GET", "/v1/vocabulary", idempotent=True, query={"kind": kind, "topic": topic}))


